WITH ValidInventory AS (SELECT *, DATE_TRUNC('MONTH', last_restock) AS last_restock_period FROM inventory WHERE store_id = 3 AND last_restock <= '2023-05-01'), summary AS (SELECT QUARTER(last_restock_period) AS last_restock_period_quarter, MAX(quantity) AS max_quantity FROM ValidInventory GROUP BY QUARTER(last_restock_period)) SELECT last_restock_period_quarter, max_quantity FROM summary WHERE max_quantity > 230 ORDER BY last_restock_period_quarter DESC;
